bool happy(const vector<vector<int>>& a,
           int line, int dr, int dc, int m) {
    int run = 1;
    if (m == 1) return true;
    for (int t = 1; t < (int)a.size(); ++t) {
        int r = dr ? t : line;
        int c = dc ? t : line;
        int pr = dr ? t - 1 : line;
        int pc = dc ? t - 1 : line;
        run = a[r][c] == a[pr][pc] ? run + 1 : 1;
        if (run == m) return true;
    }
    return false;
}
int answer = 0;
for (int i = 0; i < (int)a.size(); ++i)
    answer += happy(a, i, 0, 1, m)
            + happy(a, i, 1, 0, m);
